2090	func (f *Fetcher) resetConnectionForRestart(conn *connection) {
2091		if f.meta.Res.Range {
2092			return
2093		}
2094	
2095		// Without range support a new request always starts from byte 0,
2096		// so pause/retry must restart instead of continuing from the old offset.
2097		if conn.Chunk == nil {
2098			conn.Chunk = newChunk(0, 0)
2099		} else if !f.meta.Res.Range {
2100			conn.Chunk.Begin = 0
2101			conn.Chunk.setEnd(0)
2102			conn.Chunk.Downloaded = 0
2103		}
2104		conn.Downloaded = 0
2105		conn.Completed = false
2106		conn.speed = 0
2107		conn.lastSpeedCheck = 0
2108		conn.lastSpeedDownload = 0
2109	}
