2111	// hasSequentialPrefixLocked reports whether a single sequential connection has
2112	// a useful contiguous prefix. The caller must hold connMu.
2113	func (f *Fetcher) hasSequentialPrefixLocked(conn *connection) bool {
2114		if f.meta == nil || f.meta.Res == nil || f.meta.Res.Range || !f.rangeReprobeEligible || f.knownSize() <= 0 {
2115			return false
2116		}
2117		if conn == nil || conn.ID != 0 || len(f.connections) != 1 || conn.Chunk == nil {
2118			return false
2119		}
2120		downloaded := conn.Chunk.Downloaded
2121		return downloaded > 0 && downloaded < f.knownSize()
2122	}
