2125	// safely with If-Range. The caller must hold connMu.
2126	func (f *Fetcher) canProbeSequentialResumeLocked(conn *connection) bool {
2127		return !f.sequentialSizeUnknown && f.ifRange != "" && f.hasSequentialPrefixLocked(conn)
