579	// StartTestTemporary500Server creates a server that returns 500 for a duration, then recovers
580	// Uses slow transfer to ensure the file isn't fully downloaded during resolve phase
581	func StartTestTemporary500Server(errorDuration time.Duration) net.Listener {
582		startTime := time.Now()
583		var requestCount atomic.Int32
584	
585		return startTestServer(func(sl *shutdownListener) http.Handler {
586			mux := http.NewServeMux()
587			mux.HandleFunc("/"+BuildName, func(writer http.ResponseWriter, request *http.Request) {
588				reqNum := requestCount.Add(1)
589	
590				// First request (Resolve) succeeds with slow transfer to prevent full download
591				// Subsequent requests return 500 for the specified duration, then recover
592				if reqNum == 1 {
593					// Slow transfer for resolve: 50 microsecond per byte (~20MB/s)
594					// This ensures resolve doesn't complete the full 200MB file
595					rangeFileHandle(
596						writer,
597						request,
598						nil,
599						func(file *os.File, n int64) {
600							slowCopyNWithDelay(sl, writer, file, n, 50*time.Microsecond)
601						},
602					)
603					return
604				}
605	
606				// Subsequent requests: return 500 for errorDuration, then normal
607				if time.Since(startTime) < errorDuration {
608					writer.WriteHeader(500)
609					writer.Write([]byte("Internal Server Error"))
610					return
611				}
612	
613				rangeFileHandle(
614					writer,
615					request,
616					nil,
617					func(file *os.File, n int64) {
618						slowCopyN(sl, writer, file, n, 0)
619					},
620				)
621			})
622			return mux
623		})
624	}
625	
626	// StartTestFailThenRecoverServer creates a server that fails all connections initially,
627	// then recovers after a specified number of failed requests.
628	// This tests the retry functionality when calling Start() again after a download fails.
629	// Parameters:
630	//   - failedRequestsBeforeRecover: number of requests that will fail before server recovers
631	//
632	// Note: Uses 416 (Range Not Satisfiable) instead of 500 because 5xx errors are exempt
633	// from failure counting and will retry indefinitely. 416 is counted as a failure.
634	func StartTestFailThenRecoverServer(failedRequestsBeforeRecover int32) net.Listener {
635		var requestCount atomic.Int32
636	
637		return startTestServer(func(sl *shutdownListener) http.Handler {
638			mux := http.NewServeMux()
639			mux.HandleFunc("/"+BuildName, func(writer http.ResponseWriter, request *http.Request) {
640				reqNum := requestCount.Add(1)
641	
642				// First request (Resolve) always succeeds
643				if reqNum == 1 {
644					rangeFileHandle(
645						writer,
646						request,
647						nil,
648						func(file *os.File, n int64) {
649							io.CopyN(writer, file, n)
650						},
651					)
652					return
653				}
654	
655				// Subsequent requests fail until we've had enough failures
656				// Use 416 Range Not Satisfiable - this error is counted towards failure limit
657				if reqNum <= failedRequestsBeforeRecover+1 { // +1 because first request is resolve
658					writer.WriteHeader(416)
659					writer.Write([]byte("Range Not Satisfiable"))
660					return
661				}
662	
663				// After enough failures, server recovers
664				rangeFileHandle(
665					writer,
666					request,
667					nil,
668					func(file *os.File, n int64) {
669						io.CopyN(writer, file, n)
670					},
671				)
672			})
673			return mux
674		})
675	}
676	
677	// StartTestRangeBugServer simulate bug server:
678	// Don't follow Range request rules, always return more data than range, e.g. Range: bytes=0-100, return 150 bytes
679	func StartTestRangeBugServer() net.Listener {
680		return startTestServer(func(sl *shutdownListener) http.Handler {
681			mux := http.NewServeMux()
682			mux.HandleFunc("/"+BuildName, func(writer http.ResponseWriter, request *http.Request) {
683				rangeFileHandle(
684					writer,
685					request,
686					func(end int64) int64 {
687						var bugEnd = end
688						if end != 0 {
689							bugEnd = end + 50
690							if bugEnd >= BuildSize {
691								bugEnd = end
692							}
693						}
694						return bugEnd
695					},
696					func(file *os.File, n int64) {
697						io.CopyN(writer, file, n)
698					},
699				)
700			})
701			return mux
702		})
703	}
704	
705	func rangeFileHandle(writer http.ResponseWriter, request *http.Request, modifyEnd func(end int64) int64, iocpN func(file *os.File, n int64)) {
706		r := request.Header.Get("Range")
707	
708		// If no Range header, return full file with Accept-Ranges header
709		if r == "" {
710			// Open file first to ensure it exists
711			file, err := os.Open(BuildFile)
712			if err != nil {
713				writer.WriteHeader(500)
714				return
715			}
716			defer file.Close()
717	
718			writer.Header().Set("Content-Length", fmt.Sprintf("%d", BuildSize))
719			writer.Header().Set("Accept-Ranges", "bytes")
720			writer.WriteHeader(200)
721			(writer.(http.Flusher)).Flush()
722	
723			iocpN(file, BuildSize)
724			return
725		}
726	
727		// split range
728		s := strings.Split(r, "=")
729		if len(s) != 2 {
730			writer.WriteHeader(400)
731			return
732		}
733		s = strings.Split(s[1], "-")
734		if len(s) != 2 {
735			writer.WriteHeader(400)
736			return
737		}
738		start, err := strconv.ParseInt(s[0], 10, 64)
739		if err != nil {
740			writer.WriteHeader(400)
741			return
742		}
743		end := int64(BuildSize - 1)
744		if s[1] != "" {
745			end, err = strconv.ParseInt(s[1], 10, 64)
746			if err != nil {
747				writer.WriteHeader(400)
748				return
749			}
750		}
751		if start < 0 || end < 0 || start > end {
752			writer.WriteHeader(400)
753			return
754		}
755		if end >= BuildSize {
756			end = BuildSize - 1
757		}
758	
759		if modifyEnd != nil {
760			end = modifyEnd(end)
761		}
762	
763		// Open file before sending headers to ensure it exists
764		file, err := os.Open(BuildFile)
765		if err != nil {
766			writer.WriteHeader(500)
767			return
768		}
769		defer file.Close()
770		file.Seek(start, 0)
771	
772		writer.Header().Set("Content-Length", fmt.Sprintf("%d", end-start+1))
773		writer.Header().Set("Content-Range", fmt.Sprintf("bytes %d-%d/%d", start, end, BuildSize))
774		writer.Header().Set("Accept-Ranges", "bytes")
775		writer.WriteHeader(206)
776		(writer.(http.Flusher)).Flush()
777	
778		iocpN(file, end-start+1)
779	}
780	
781	// slowCopyN copies n bytes from src to dst, speed limit is bytes per second
782	func slowCopy(sl *shutdownListener, dst io.Writer, src io.Reader, delay int64) (written int64, err error) {
783		buf := make([]byte, 32*1024)
784		for {
785			if sl.isShutdown {
786				return 0, errors.New("server shutdown")
787			}
788			nr, er := src.Read(buf)
789			if nr > 0 {
790				nw, ew := dst.Write(buf[0:nr])
791				if nw > 0 {
792					written += int64(nw)
793				}
794				if ew != nil {
795					err = ew
796					break
797				}
798				if nr != nw {
799					err = io.ErrShortWrite
800					break
801				}
802			}
803			if er != nil {
804				if er != io.EOF {
805					err = er
806				}
807				break
808			}
809			if delay > 0 {
810				time.Sleep(time.Millisecond * time.Duration(delay))
811			}
812		}
813		return written, err
814	}
815	
816	func slowCopyN(sl *shutdownListener, dst io.Writer, src io.Reader, n int64, delay int64) (written int64, err error) {
817		written, err = slowCopy(sl, dst, io.LimitReader(src, n), delay)
818		if written == n {
819			return n, nil
820		}
821		if written < n && err == nil {
822			// src stopped early; must have been EOF.
823			err = io.EOF
824		}
825		return
826	}
827	
828	// slowCopyAfterDelay sleeps once before performing a normal copy to simulate a single timeout.
829	func slowCopyAfterDelay(sl *shutdownListener, dst io.Writer, src io.Reader, n int64, delay int64) (written int64, err error) {
830		if delay > 0 {
831			time.Sleep(time.Millisecond * time.Duration(delay))
832		}
833		return slowCopyN(sl, dst, src, n, 0)
834	}
835	
836	func startTestServer(serverHandle func(sl *shutdownListener) http.Handler) net.Listener {
837		listener, err := net.Listen("tcp", "127.0.0.1:0")
838		if err != nil {
839			panic(err)
840		}
841		file, err := os.Create(BuildFile)
842		if err != nil {
843			panic(err)
844		}
845		defer file.Close()
846		// Write random data
847		l := int64(8192)
848		buf := make([]byte, l)
849		size := int64(0)
850		for {
851			_, err := rand.Read(buf)
852			if err != nil {
853				panic(err)
854			}
855			if size+l >= BuildSize {
856				file.WriteAt(buf[0:BuildSize-size], size)
857				break
858			}
859			file.WriteAt(buf, size)
860			size += l
861		}
862		server := &http.Server{}
863		sl := &shutdownListener{
864			server:   server,
865			Listener: listener,
866		}
867		server.Handler = serverHandle(sl)
868		go server.Serve(listener)
869	
870		return sl
871	}
872	
873	type shutdownListener struct {
874		server     *http.Server
875		isShutdown bool
876		net.Listener
877	}
878	
879	func (c *shutdownListener) Close() error {
880		// Shutdown server first (waits for in-flight requests), then set isShutdown
881		closeErr := c.server.Shutdown(context.Background())
882		c.isShutdown = true
883		if err := ifExistAndRemove(BuildFile); err != nil {
884			fmt.Println(err)
885		}
886		if err := ifExistAndRemove(DownloadFile); err != nil {
887			fmt.Println(err)
888		}
889		if err := ifExistAndRemove(DownloadRenameFile); err != nil {
890			fmt.Println(err)
891		}
892		return closeErr
893	}
894	
895	func ifExistAndRemove(name string) error {
896		if _, err := os.Stat(name); !os.IsNotExist(err) {
897			return os.Remove(name)
898		}
899		return nil
900	}
901	
902	func StartSocks5Server(usr, pwd string) net.Listener {
903		conf := &socks5.Config{}
904		if usr != "" && pwd != "" {
905			conf.Credentials = socks5.StaticCredentials{
906				usr: pwd,
907			}
908		}
909	
910		server, err := socks5.New(conf)
911		if err != nil {
912			panic(err)
913		}
914	
915		listener, err := net.Listen("tcp", "127.0.0.1:0")
916		if err != nil {
917			panic(err)
918		}
919		go server.Serve(listener)
920		return listener
921	}
922	
923	// StartTestPatchURLServer creates a server with two endpoints:
924	// - /bad-url: always returns 404 (simulates a broken download link)
925	// - /good-url: returns the file successfully (simulates a working download link)
926	// This is used to test the Patch functionality where a failed download URL can be
927	// replaced with a working one.
928	func StartTestPatchURLServer() net.Listener {
929		return startTestServer(func(sl *shutdownListener) http.Handler {
930			mux := http.NewServeMux()
931			// Bad URL - always fails with 404
932			mux.HandleFunc("/bad-url", func(writer http.ResponseWriter, request *http.Request) {
933				writer.WriteHeader(404)
934				writer.Write([]byte("Not Found"))
935			})
936			// Good URL - returns the file successfully with range support
937			mux.HandleFunc("/good-url", func(writer http.ResponseWriter, request *http.Request) {
938				rangeFileHandle(
939					writer,
940					request,
941					nil,
942					func(file *os.File, n int64) {
943						io.CopyN(writer, file, n)
944					},
945				)
946			})
947			return mux
948		})
949	}
950	
951	// StartTestCookieExpiringServer creates a server that simulates cookie expiration during download.
952	// - First request (Resolve): accepts "session=old_token" and succeeds
953	// - Subsequent requests: "session=old_token" is expired (returns 401), only "session=new_token" works
954	// This is used to test the Patch functionality where a cookie expires mid-download,
955	// requiring the user to patch with a new cookie to resume.
956	func StartTestCookieExpiringServer() net.Listener {
957		var requestCount atomic.Int32
958	
959		return startTestServer(func(sl *shutdownListener) http.Handler {
960			mux := http.NewServeMux()
961			mux.HandleFunc("/"+BuildName, func(writer http.ResponseWriter, request *http.Request) {
962				reqNum := requestCount.Add(1)
963				cookie := request.Header.Get("Cookie")
964	
965				// First request (Resolve): accept old_token
966				if reqNum == 1 {
967					if !strings.Contains(cookie, "session=old_token") {
968						writer.WriteHeader(401)
969						writer.Write([]byte("Unauthorized: Invalid cookie"))
970						return
971					}
972					// Return file info for resolve (with range support)
973					rangeFileHandle(
974						writer,
975						request,
976						nil,
977						func(file *os.File, n int64) {
978							io.CopyN(writer, file, n)
979						},
980					)
981					return
982				}
983	
984				// Subsequent requests: old_token is expired, only new_token works
985				if strings.Contains(cookie, "session=new_token") {
986					// New token is valid - return the file with range support
987					rangeFileHandle(
988						writer,
989						request,
990						nil,
991						func(file *os.File, n int64) {
992							io.CopyN(writer, file, n)
993						},
994					)
995					return
996				}
997	
998				// Old token or invalid token - return 401
999				writer.WriteHeader(401)
1000				writer.Write([]byte("Unauthorized: Cookie expired"))
1001			})
1002			return mux
1003		})
1004	}
